import re

def calistir(program):
    # Değişkenleri tutacak sözlük
    degiskenler = {}

    # Satır satır böl
    lines = program.splitlines()

    # Son ifadeyi saklamak için bir değişken
    son_deger = None

    for line in lines:
        line = line.strip()

        # Yorum varsa ayır
        comment_match = re.search(r'#.*$', line)
        if comment_match:
            line = line[:comment_match.start()].strip()

        # Boş satırı geç
        if not line:
            continue

        # Atama mı?
        assign_match = re.match(r'^([a-zA-Z_][a-zA-Z0-9_]*)\s*=\s*(.*)$', line)
        if assign_match:
            var_name = assign_match.group(1)
            expression = assign_match.group(2)

            try:
                value = deger_hesapla(expression, degiskenler)
                degiskenler[var_name] = value
                son_deger = value
            except Exception as e:
                raise e

        else:
            # Sadece ifadeyse hesapla ve son_deger yap
            try:
                son_deger = deger_hesapla(line, degiskenler)
            except Exception as e:
                raise e

    return son_deger


def deger_hesapla(ifade, degiskenler):
    # Parantezleri ayır
    tokens = re.findall(r'\d+(?:\.\d+)?|[a-zA-Z_][a-zA-Z0-9_]*|\*\*|[-+\*/%()]', ifade)

    if not tokens:
        return None

    # Değişkenlerin isimleri ve değerleri
    def replace_var(match):
        var = match.group(0)
        if var in degiskenler:
            return str(degiskenler[var])
        else:
            raise NameError(f"Name '{var}' is not defined")

    # Değişkenleri yerine koy
    replaced = re.sub(r'[a-zA-Z_][a-zA-Z0-9_]*', replace_var, ifade)

    # Sayılarla çalış
    try:
        # Daha karmaşık hesaplamalar için özel işlem:
        # Önce parantezlerdeki işlemler, sonra **, ardından *, /, %, + ve -
        # Bu kurala göre sadece basit bir şekilde yapılandıracağım.

        # Öncelikle tüm sayıları ayırt et
        tokens = re.findall(r'\d+(?:\.\d+)?|[a-zA-Z_][a-zA-Z0-9_]*|\*\*|[-+\*/%()]', replaced)

        if not tokens:
            raise SyntaxError("Invalid expression")

        # Fonksiyonlara göre işlem yap
        result = hesapla_tokens(tokens, degiskenler)
        return result

    except ZeroDivisionError:
        raise ZeroDivisionError("division by zero")
    except Exception as e:
        if "Name" in str(e):
            raise NameError(str(e))
        elif "Syntax" in str(e):
            raise SyntaxError("Invalid syntax")
        else:
            # Diğer hatalar için
            raise


# Fonksiyonlar: min, max, abs
def hesapla_tokens(tokens, degiskenler):
    def solve():
        # Değişkenleri bul ve işlem yap
        stack = []
        operators = set(['+', '-', '*', '/', '%', '**'])

        for token in tokens:
            if re.match(r'^\d+(?:\.\d+)?$', token):  # Sayısal ifade
                stack.append(float(token))
            elif token in operators or token == 'abs' or token == 'min' or token == 'max':
                stack.append(token)
            else:  # Değişken ismi
                if token not in degiskenler:
                    raise NameError(f"Name '{token}' is not defined")
                stack.append(float(degiskenler[token]))

        # Operatörleri sırayla uygula (soldan sağa, öncelikle ** sonra işlemler)
