            if len(stack) >= 3 and isinstance(stack[-2], str):
                op = stack.pop()
                b = float(stack.pop())
                a = float(stack.pop())

                if op == '+':
                    result = a + b
                elif op == '-':
                    result = a - b
                elif op == '*':
                    result = a * b
                elif op == '/':
                    if b == 0:
                        raise ZeroDivisionError("division by zero")
                    result = a / b
                elif op == '%':
                    if b == 0:
                        raise ZeroDivisionError("division by zero")
                    result = a % b
                elif op == '**':
                    result = a ** b
                else:
                    # Fonksiyonlar
                    if op == 'abs':
                        result = abs(b)
